import { test, expect } from '@playwright/test';

test.describe('Currency Field Formatting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should format currency input with commas and two decimal places', async ({ page }) => {
    // Locate and interact with the currency input using getByLabel
    const currencyInput = page.getByLabel('Currency Amount');
    await expect(currencyInput).toBeVisible();

    // Set initial value to test formatting
    await currencyInput.fill('123456789012345678901234567890');

    // Verify initial value is displayed correctly
    const valueDisplay = page.getByText('123,456,789,012,345,678,901,234,567,890');
    await expect(valueDisplay).toBeVisible();

    // Verify input has correct format
    await expect(currencyInput).toHaveValue('123,456,789,012,345,678,901,234,567,890');

    // Verify input is not editable
    await expect(currencyInput).not.toBeEditable();

    // Verify input has proper validation state
    await expect(currencyInput).toHaveClass(/valid|invalid/);

    // Verify error message is not displayed
    const errorMessage = page.getByText('Invalid format');
    await expect(errorMessage).not.toBeVisible();

    // Verify currency formatting is applied
    const formattedValue = page.getByText('123,456,789,012,345,678,901,234,567,890');
    await expect(formattedValue).toBeVisible();

    // Verify formatting persists after focus loss
    await currencyInput.blur();
    await expect(formattedValue).toBeVisible();
  });

  test('should handle negative currency values with proper formatting', async ({ page }) => {
    // Locate and interact with the currency input using getByLabel
    const currencyInput = page.getByLabel('Currency Amount');
    await expect(currencyInput).toBeVisible();

    // Set negative value to test formatting
    await currencyInput.fill('-123456789012345678901234567890');

    // Verify negative value is displayed correctly
    const valueDisplay = page.getByText('-123,456,789,012,345,678,901,234,567,890');
    await expect(valueDisplay).toBeVisible();

    // Verify input has correct format
    await expect(currencyInput).toHaveValue('-123,456,789,012,345,678,901,234,567,890');

    // Verify input is not editable
    await expect(currencyInput).not.toBeEditable();

    // Verify input has proper validation state
    await expect(currencyInput).toHaveClass(/valid|invalid/);

    // Verify error message is not displayed
    const errorMessage = page.getByText('Invalid format');
    await expect(errorMessage).not.toBeVisible();

    // Verify negative sign is preserved
    const negativeSign = page.getByText('-');
    await expect(negativeSign).toBeVisible();

    // Verify formatting persists after focus loss
    await currencyInput.blur();
    await expect(negativeSign).toBeVisible();
  });
});
